1	//! Budget governance policy engine for RTK Codeflow.
2	//!
3	//! Evaluates spending limits against accumulated cost data and returns
4	//! Allow / Warn / Block verdicts for PreToolUse hook enforcement.
5	//!
6	//! Config load order:
7	//!   1. `.codeflow/budget.toml`       (project-scoped)
8	//!   2. `~/.config/rtk/budget.toml`   (user-global)
9	//!   3. Default: no limits (all Allow)
10	
11	use anyhow::Result;
12	use std::path::PathBuf;
13	
14	use super::cost_store::CostStore;
15	
16	// ── Public types ──────────────────────────────────────────────────────────────
17	
18	/// Action to take when a limit is exceeded.
19	#[derive(Debug, Clone, PartialEq)]
20	pub enum LimitAction {
21	    Warn,
22	    Block,
23	}
24	
25	/// Scope for a budget limit.
26	#[derive(Debug, Clone, PartialEq)]
27	pub enum PolicyScope {
28	    Developer,
29	    Project,
30	    Team,
31	}
32	
33	/// Budget accounting period.
34	#[derive(Debug, Clone, PartialEq)]
35	pub enum BudgetPeriod {
36	    Monthly,
37	    Weekly,
38	    Daily,
39	}
40	
41	/// A single limit rule loaded from TOML.
42	#[derive(Debug, Clone)]
43	pub struct PolicyLimit {
44	    pub scope: PolicyScope,
45	    /// Exact name or `"*"` wildcard.
46	    pub id: String,
47	    pub max_usd: f64,
48	    pub action_on_exceed: LimitAction,
49	}
50	
51	/// Global settings loaded from the `[global]` table.
52	#[derive(Debug, Clone)]
53	pub struct GlobalSettings {
54	    pub period: BudgetPeriod,
55	    /// Warn threshold as percentage (0–100).
56	    pub warn_at_pct: f64,
57	    /// Block threshold as percentage (0–100).
58	    pub block_at_pct: f64,
59	}
60	
61	impl Default for GlobalSettings {
62	    fn default() -> Self {
63	        Self {
64	            period: BudgetPeriod::Monthly,
65	            warn_at_pct: 75.0,
66	            block_at_pct: 100.0,
67	        }
68	    }
69	}
70	
71	/// Full policy configuration deserialized from TOML.
72	#[derive(Debug, Clone)]
73	pub struct PolicyConfig {
74	    pub global: GlobalSettings,
75	    pub limits: Vec<PolicyLimit>,
76	}
77	
78	impl Default for PolicyConfig {
79	    fn default() -> Self {
80	        Self {
81	            global: GlobalSettings::default(),
82	            limits: vec![],
83	        }
84	    }
85	}
86	
87	impl PolicyConfig {
88	    /// Load config from the first found path, falling back to Default.
89	    pub fn load() -> Self {
90	        let candidates: Vec<PathBuf> = vec![
91	            PathBuf::from(".codeflow/budget.toml"),
92	            dirs::config_dir()
93	                .unwrap_or_else(|| PathBuf::from("."))
94	                .join("rtk")
95	                .join("budget.toml"),
96	        ];
97	
98	        for path in &candidates {
99	            if let Ok(content) = std::fs::read_to_string(path) {
100	                match parse_toml_config(&content) {
101	                    Ok(cfg) => return cfg,
102	                    Err(e) => {
103	                        eprintln!("[rtk budget] failed to parse {}: {}", path.display(), e);
104	                    }
105	                }
106	            }
107	        }
108	
109	        Self::default()
110	    }
111	}
112	
113	/// Verdict returned by the policy engine.
114	#[derive(Debug, Clone, PartialEq)]
115	pub enum Verdict {
116	    Allow,
117	    Warn(String),
118	    Block(String),
119	}
120	
121	/// Policy evaluation engine. Holds config and evaluates against CostStore.
122	pub struct PolicyEngine {
123	    pub config: PolicyConfig,
124	}
125	
126	impl PolicyEngine {
127	    pub fn new(config: PolicyConfig) -> Self {
128	        Self { config }
129	    }
130	
131	    /// Evaluate all matching limits for the given context.
132	    ///
133	    /// Returns the worst verdict (Block > Warn > Allow).
134	    pub fn evaluate(&self, cost_store: &CostStore, dev_id: &str, project: &str) -> Verdict {
135	        if self.config.limits.is_empty() {
136	            return Verdict::Allow;
137	        }
138	
139	        let since = period_start(&self.config.global.period);
140	        let g = &self.config.global;
141	        let mut worst = Verdict::Allow;
142	
143	        for limit in &self.config.limits {
144	            let spent = match &limit.scope {
145	                PolicyScope::Developer => {
146	                    let target = if limit.id == "*" { dev_id } else { &limit.id };
147	                    cost_store
148	                        .accumulated_cost_by_dev(target, &since)
149	                        .unwrap_or(0.0)
150	                }
151	                PolicyScope::Project => {
152	                    let target = if limit.id == "*" { project } else { &limit.id };
153	                    cost_store
154	                        .accumulated_cost_by_project(target, &since)
155	                        .unwrap_or(0.0)
156	                }
157	                // Team scope: sum across all records in the period (team = global budget)
158	                PolicyScope::Team => cost_store.total_cost_since(&since).unwrap_or(0.0),
159	            };
160	
161	            let pct = if limit.max_usd > 0.0 {
162	                (spent / limit.max_usd) * 100.0
163	            } else {
164	                0.0
165	            };
166	
167	            // Determine verdict for this specific limit
168	            let v = if pct >= g.block_at_pct && limit.action_on_exceed == LimitAction::Block {
169	                Verdict::Block(format!(
170	                    "Budget limit exceeded: {} '{}' spent ${:.4} / ${:.2} ({:.1}%)",
171	                    scope_label(&limit.scope),
172	                    limit.id,
173	                    spent,
174	                    limit.max_usd,
175	                    pct
176	                ))
177	            } else if pct >= g.warn_at_pct {
178	                Verdict::Warn(format!(
179	                    "Budget warning: {} '{}' spent ${:.4} / ${:.2} ({:.1}%)",
180	                    scope_label(&limit.scope),
181	                    limit.id,
182	                    spent,
183	                    limit.max_usd,
184	                    pct
185	                ))
186	            } else {
187	                Verdict::Allow
188	            };
189	
190	            worst = worst_verdict(worst, v);
191	        }
192	
193	        worst
194	    }
195	}
196	
197	// ── Period calculation ────────────────────────────────────────────────────────
198	
199	/// Return the RFC3339 timestamp of the start of the current period.
200	pub fn period_start(period: &BudgetPeriod) -> String {
201	    use chrono::{Datelike, TimeZone, Utc};
202	    let now = Utc::now();
203	    let dt = match period {
204	        BudgetPeriod::Daily => {
205	            Utc.with_ymd_and_hms(now.year(), now.month(), now.day(), 0, 0, 0)
206	                .single()
207	                .unwrap_or(now)
208	        }
209	        BudgetPeriod::Weekly => {
210	            // Monday of the current ISO week
211	            let weekday_num = now.weekday().num_days_from_monday(); // 0=Mon
212	            let day = now.day().saturating_sub(weekday_num);
213	            Utc.with_ymd_and_hms(now.year(), now.month(), day.max(1), 0, 0, 0)
214	                .single()
215	                .unwrap_or(now)
216	        }
217	        BudgetPeriod::Monthly => {
218	            Utc.with_ymd_and_hms(now.year(), now.month(), 1, 0, 0, 0)
219	                .single()
220	                .unwrap_or(now)
221	        }
222	    };
223	    dt.to_rfc3339()
224	}
225	
226	// ── TOML parsing ──────────────────────────────────────────────────────────────
227	
228	fn parse_toml_config(content: &str) -> Result<PolicyConfig> {
229	    let doc: toml::Value = toml::from_str(content)?;
230	
231	    let global = parse_global(&doc);
232	    let limits = parse_limits(&doc)?;
233	
234	    Ok(PolicyConfig { global, limits })
235	}
236	
237	fn parse_global(doc: &toml::Value) -> GlobalSettings {
238	    let mut settings = GlobalSettings::default();
239	
240	    let Some(g) = doc.get("global") else {
241	        return settings;
242	    };
243	
244	    if let Some(p) = g.get("period").and_then(|v| v.as_str()) {
245	        settings.period = match p {
246	            "weekly" => BudgetPeriod::Weekly,
247	            "daily" => BudgetPeriod::Daily,
248	            _ => BudgetPeriod::Monthly,
249	        };
250	    }
251	    if let Some(w) = g.get("warn_at_pct").and_then(|v| v.as_float()) {
252	        settings.warn_at_pct = w;
253	    } else if let Some(w) = g.get("warn_at_pct").and_then(|v| v.as_integer()) {
254	        settings.warn_at_pct = w as f64;
255	    }
256	    if let Some(b) = g.get("block_at_pct").and_then(|v| v.as_float()) {
257	        settings.block_at_pct = b;
258	    } else if let Some(b) = g.get("block_at_pct").and_then(|v| v.as_integer()) {
259	        settings.block_at_pct = b as f64;
260	    }
261	
262	    settings
263	}
264	
265	fn parse_limits(doc: &toml::Value) -> Result<Vec<PolicyLimit>> {
266	    let arr = match doc.get("limits").and_then(|v| v.as_array()) {
267	        Some(a) => a,
268	        None => return Ok(vec![]),
269	    };
270	
271	    let mut limits = Vec::with_capacity(arr.len());
272	    for item in arr {
273	        let scope_str = item
274	            .get("scope")
275	            .and_then(|v| v.as_str())
276	            .unwrap_or("developer");
277	        let scope = match scope_str {
278	            "project" => PolicyScope::Project,
279	            "team" => PolicyScope::Team,
280	            _ => PolicyScope::Developer,
281	        };
282	
283	        let id = item
284	            .get("id")
285	            .and_then(|v| v.as_str())
286	            .unwrap_or("*")
287	            .to_string();
288	
289	        let max_usd = item
290	            .get("max_usd")
291	            .and_then(|v| v.as_float())
292	            .or_else(|| {
293	                item.get("max_usd")
294	                    .and_then(|v| v.as_integer())
295	                    .map(|i| i as f64)
296	            })
297	            .unwrap_or(0.0);
298	
299	        let action_str = item
300	            .get("action_on_exceed")
301	            .and_then(|v| v.as_str())
302	            .unwrap_or("warn");
303	        let action_on_exceed = if action_str == "block" {
304	            LimitAction::Block
305	        } else {
306	            LimitAction::Warn
307	        };
308	
309	        limits.push(PolicyLimit {
310	            scope,
311	            id,
312	            max_usd,
313	            action_on_exceed,
314	        });
315	    }
316	    Ok(limits)
317	}
318	
319	// ── Helpers ───────────────────────────────────────────────────────────────────
320	
321	fn scope_label(scope: &PolicyScope) -> &'static str {
322	    match scope {
323	        PolicyScope::Developer => "developer",
324	        PolicyScope::Project => "project",
325	        PolicyScope::Team => "team",
326	    }
327	}
328	
329	/// Return the more severe of two verdicts (Block > Warn > Allow).
330	fn worst_verdict(a: Verdict, b: Verdict) -> Verdict {
331	    match (&a, &b) {
332	        (Verdict::Block(_), _) => a,
333	        (_, Verdict::Block(_)) => b,
334	        (Verdict::Warn(_), _) => a,
335	        (_, Verdict::Warn(_)) => b,
336	        _ => Verdict::Allow,
337	    }
338	}
