347	        let dir = tempfile::tempdir().unwrap();
348	        let db_path = dir.path().join("test_cost.db");
349	        let store = CostStore::open(&db_path).unwrap();
350	
351	        let now = chrono::Utc::now().to_rfc3339();
352	        for (dev, project, cost) in records {
353	            let record = crate::core::cost_store::CostRecord {
354	                id: None,
355	                session_id: "sess".to_string(),
356	                model_id: "claude-sonnet-4-20250514".to_string(),
357	                input_tokens: 1000,
358	                output_tokens: 500,
359	                cache_read_tokens: 0,
360	                cache_write_tokens: 0,
361	                cost_usd: *cost,
362	                pr_ref: None,
363	                feature_tag: None,
364	                project_path: project.to_string(),
365	                developer_id: dev.to_string(),
366	                timestamp: now.clone(),
