374	    #[test]
375	    fn parse_valid_config() {
376	        let toml = r#"
377	[global]
378	period = "monthly"
379	warn_at_pct = 75
380	block_at_pct = 100
381	
382	[[limits]]
383	scope = "developer"
384	id = "*"
385	max_usd = 500.0
386	action_on_exceed = "warn"
387	
388	[[limits]]
389	scope = "team"
390	id = "platform"
391	max_usd = 10000.0
392	action_on_exceed = "block"
393	"#;
394	        let cfg = parse_toml_config(toml).unwrap();
395	        assert_eq!(cfg.global.period, BudgetPeriod::Monthly);
396	        assert!((cfg.global.warn_at_pct - 75.0).abs() < f64::EPSILON);
397	        assert_eq!(cfg.limits.len(), 2);
398	        assert_eq!(cfg.limits[0].scope, PolicyScope::Developer);
399	        assert_eq!(cfg.limits[0].id, "*");
400	        assert_eq!(cfg.limits[1].scope, PolicyScope::Team);
401	        assert_eq!(cfg.limits[1].action_on_exceed, LimitAction::Block);
402	    }
