517	    #[test]
518	    fn block_beats_warn_in_worst_verdict() {
519	        let a = Verdict::Warn("w".to_string());
520	        let b = Verdict::Block("b".to_string());
521	        assert!(matches!(worst_verdict(a.clone(), b.clone()), Verdict::Block(_)));
522	        assert!(matches!(worst_verdict(b, a), Verdict::Block(_)));
523	    }
