1	//! `rtk budget` — budget governance status for the current project.
2	//!
3	//! Shows accumulated spend vs limits for all configured policy scopes.
4	//!
5	//! Usage:
6	//!   rtk budget           — human-readable table
7	//!   rtk budget --json    — machine-readable JSON
8	
9	use anyhow::{Context, Result};
10	use colored::Colorize;
11	use serde::Serialize;
12	
13	use crate::core::budget_policy::{
14	    BudgetPeriod, LimitAction, PolicyConfig, PolicyEngine, PolicyScope, Verdict, period_start,
15	};
16	use crate::core::cost_store::CostStore;
17	
18	/// One row in the budget status table.
19	#[derive(Debug, Serialize)]
20	pub struct BudgetRow {
21	    pub scope: String,
22	    pub id: String,
23	    pub spent_usd: f64,
24	    pub limit_usd: f64,
25	    pub pct: f64,
26	    pub status: String,
27	}
28	
29	pub fn run_budget(json: bool) -> Result<()> {
30	    let config = PolicyConfig::load();
31	    let store = CostStore::new().context("failed to open cost store")?;
32	
33	    if config.limits.is_empty() {
34	        if json {
35	            println!("[]");
36	        } else {
37	            println!("{}", "Budget Policy".bold());
38	            println!("{}", "─".repeat(50));
39	            println!("No budget limits configured.");
40	            println!("Create .codeflow/budget.toml or ~/.config/rtk/budget.toml to set limits.");
41	            println!();
42	            println!("See: rtk data/budget-policy-example.toml for format reference.");
43	        }
44	        return Ok(());
45	    }
46	
47	    let since = period_start(&config.global.period);
48	    let dev_id = whoami();
49	    let project = current_project();
50	
51	    let mut rows: Vec<BudgetRow> = Vec::with_capacity(config.limits.len());
52	
53	    for limit in &config.limits {
54	        let spent = match &limit.scope {
55	            PolicyScope::Developer => {
56	                let target = if limit.id == "*" { &dev_id } else { &limit.id };
57	                store.accumulated_cost_by_dev(target, &since).unwrap_or(0.0)
58	            }
59	            PolicyScope::Project => {
60	                let target = if limit.id == "*" { &project } else { &limit.id };
61	                store
62	                    .accumulated_cost_by_project(target, &since)
63	                    .unwrap_or(0.0)
64	            }
65	            PolicyScope::Team => store.total_cost_since(&since).unwrap_or(0.0),
66	        };
67	
68	        let pct = if limit.max_usd > 0.0 {
69	            (spent / limit.max_usd) * 100.0
70	        } else {
71	            0.0
72	        };
73	
74	        let g = &config.global;
75	        let status = if pct >= g.block_at_pct && limit.action_on_exceed == LimitAction::Block {
76	            "BLOCKED"
77	        } else if pct >= g.warn_at_pct {
78	            "WARN"
79	        } else {
80	            "OK"
81	        };
82	
83	        let scope_label = match &limit.scope {
84	            PolicyScope::Developer => "developer",
85	            PolicyScope::Project => "project",
86	            PolicyScope::Team => "team",
87	        };
88	
89	        rows.push(BudgetRow {
90	            scope: scope_label.to_string(),
91	            id: limit.id.clone(),
92	            spent_usd: spent,
93	            limit_usd: limit.max_usd,
94	            pct,
95	            status: status.to_string(),
96	        });
97	    }
98	
99	    if json {
100	        println!("{}", serde_json::to_string_pretty(&rows)?);
101	        return Ok(());
102	    }
103	
104	    // Human-readable table
105	    let period_label = match config.global.period {
106	        BudgetPeriod::Monthly => "monthly",
107	        BudgetPeriod::Weekly => "weekly",
108	        BudgetPeriod::Daily => "daily",
109	    };
110	
111	    println!("{}", "Budget Status".bold());
112	    println!(
113	        "  Period: {}  |  Warn at: {}%  |  Block at: {}%",
114	        period_label,
115	        config.global.warn_at_pct as u32,
116	        config.global.block_at_pct as u32,
117	    );
118	    println!("{}", "─".repeat(72));
119	    println!(
120	        "  {:<12} {:<24} {:>10} {:>10} {:>8} {:>8}",
121	        "SCOPE".bold(),
122	        "ID".bold(),
123	        "SPENT".bold(),
124	        "LIMIT".bold(),
125	        "PCT".bold(),
126	        "STATUS".bold(),
127	    );
128	    println!("  {}", "─".repeat(68));
129	
130	    for row in &rows {
131	        let status_colored = match row.status.as_str() {
132	            "BLOCKED" => row.status.red().bold().to_string(),
133	            "WARN" => row.status.yellow().bold().to_string(),
134	            _ => row.status.green().to_string(),
135	        };
136	
137	        let pct_colored = {
138	            let s = format!("{:.1}%", row.pct);
139	            if row.pct >= config.global.block_at_pct {
140	                s.red().to_string()
141	            } else if row.pct >= config.global.warn_at_pct {
142	                s.yellow().to_string()
143	            } else {
144	                s.green().to_string()
145	            }
146	        };
147	
148	        println!(
149	            "  {:<12} {:<24} {:>10} {:>10} {:>8} {:>8}",
150	            truncate(&row.scope, 12),
151	            truncate(&row.id, 24),
152	            format_usd(row.spent_usd).yellow().to_string(),
153	            format_usd(row.limit_usd),
154	            pct_colored,
155	            status_colored,
156	        );
157	    }
158	
159	    // Summary verdict
160	    let engine = PolicyEngine::new(config);
161	    let verdict = engine.evaluate(&store, &dev_id, &project);
162	    println!();
163	    match verdict {
164	        Verdict::Allow => println!("  {}", "All limits OK".green()),
165	        Verdict::Warn(msg) => println!("  {}", format!("Warning: {}", msg).yellow()),
166	        Verdict::Block(msg) => println!("  {}", format!("BLOCKED: {}", msg).red().bold()),
167	    }
168	
169	    Ok(())
170	}
