178	fn truncate(s: &str, max: usize) -> String {
179	    if s.len() <= max {
180	        s.to_string()
181	    } else {
182	        let end = s
183	            .char_indices()
184	            .take_while(|(i, _)| *i < max.saturating_sub(2))
185	            .last()
186	            .map(|(i, c)| i + c.len_utf8())
187	            .unwrap_or(0);
188	        format!("{}..", &s[..end])
189	    }
190	}
