1	//! Processes incoming hook calls from AI agents and rewrites commands on the fly.
2	//!
3	//! Uses `writeln!(stdout, ...)` instead of `println!` — accidental stdout/stderr
4	//! corrupts the JSON protocol (Claude Code bug #4669 silently disables the hook).
5	
6	use super::constants::PRE_TOOL_USE_KEY;
7	use super::permissions::{self, PermissionVerdict};
8	use anyhow::{Context, Result};
9	use serde_json::{json, Value};
10	use std::io::{self, Read, Write};
11	
12	use crate::core::budget_policy::{PolicyConfig, PolicyEngine, Verdict};
13	use crate::core::content_hash;
14	use crate::core::cost_store::CostStore;
15	use crate::core::pr_linker;
16	use crate::core::provenance::{self, ProvenanceStore};
17	use crate::discover::registry::{has_heredoc, rewrite_command};
18	
19	const STDIN_CAP: usize = 1_048_576; // 1 MiB
20	
21	fn read_stdin_limited() -> Result<String> {
22	    let mut input = String::new();
23	    io::stdin()
24	        .take((STDIN_CAP + 1) as u64)
25	        .read_to_string(&mut input)
26	        .context("Failed to read stdin")?;
27	    if input.len() > STDIN_CAP {
28	        anyhow::bail!("hook stdin exceeds {} byte limit", STDIN_CAP);
29	    }
30	    Ok(input)
31	}
32	
33	// ── Copilot hook (VS Code + Copilot CLI) ──────────────────────
34	
35	/// Format detected from the preToolUse JSON input.
36	enum HookFormat {
37	    /// VS Code Copilot Chat / Claude Code: `tool_name` + `tool_input.command`, supports `updatedInput`.
38	    VsCode { command: String },
39	    /// GitHub Copilot CLI: camelCase `toolName` + `toolArgs` (JSON string), supports `modifiedArgs` for transparent rewrite.
40	    /// Carries the full parsed `toolArgs` object so we can rewrite `command` while preserving
41	    /// host-supplied metadata (description, initial_wait, mode, …) the tool requires.
42	    CopilotCli { command: String, args: Value },
43	    /// Non-bash tool, already uses rtk, or unknown format — pass through silently.
44	    PassThrough,
45	}
46	
47	/// Run the Copilot preToolUse hook.
48	/// Auto-detects VS Code Copilot Chat vs Copilot CLI format.
49	pub fn run_copilot() -> Result<()> {
50	    let input = read_stdin_limited()?;
51	
52	    // Strip leading BOM(s) before trimming: some Windows hosts prepend UTF-8
53	    // BOMs to hook stdin (confirmed for Cursor), which serde_json rejects.
54	    let input = strip_leading_bom(&input).trim();
55	    if input.is_empty() {
56	        return Ok(());
57	    }
58	
59	    let v: Value = match serde_json::from_str(input) {
60	        Ok(v) => v,
61	        Err(e) => {
62	            let _ = writeln!(io::stderr(), "[rtk hook] Failed to parse JSON input: {e}");
63	            return Ok(());
64	        }
65	    };
66	
67	    match detect_format(&v) {
68	        HookFormat::VsCode { command } => handle_vscode(&command),
69	        HookFormat::CopilotCli { command, args } => handle_copilot_cli(&command, &args),
70	        HookFormat::PassThrough => Ok(()),
71	    }
72	}
73	
74	fn detect_format(v: &Value) -> HookFormat {
75	    // VS Code Copilot Chat / Claude Code: snake_case keys
76	    if let Some(tool_name) = v.get("tool_name").and_then(|t| t.as_str()) {
77	        if matches!(tool_name, "runTerminalCommand" | "Bash" | "bash") {
78	            if let Some(cmd) = v
79	                .pointer("/tool_input/command")
80	                .and_then(|c| c.as_str())
81	                .filter(|c| !c.is_empty())
82	            {
83	                return HookFormat::VsCode {
84	                    command: cmd.to_string(),
85	                };
86	            }
87	        }
88	        return HookFormat::PassThrough;
89	    }
90	
91	    // Copilot CLI: camelCase keys, toolArgs is a JSON-encoded string
92	    if let Some(tool_name) = v.get("toolName").and_then(|t| t.as_str()) {
93	        if tool_name == "bash" {
94	            if let Some(tool_args_str) = v.get("toolArgs").and_then(|t| t.as_str()) {
95	                if let Ok(tool_args) = serde_json::from_str::<Value>(tool_args_str) {
96	                    if let Some(cmd) = tool_args
97	                        .get("command")
98	                        .and_then(|c| c.as_str())
99	                        .filter(|c| !c.is_empty())
100	                    {
101	                        return HookFormat::CopilotCli {
102	                            command: cmd.to_string(),
103	                            args: tool_args,
104	                        };
105	                    }
106	                }
107	            }
108	        }
109	        return HookFormat::PassThrough;
110	    }
111	
112	    HookFormat::PassThrough
113	}
114	
115	fn get_rewritten(cmd: &str) -> Option<String> {
116	    if has_heredoc(cmd) {
117	        return None;
118	    }
119	
120	    let (excluded, transparent_prefixes) = crate::core::config::Config::load()
121	        .map(|c| (c.hooks.exclude_commands, c.hooks.transparent_prefixes))
122	        .unwrap_or_default();
123	
124	    let rewritten = rewrite_command(cmd, &excluded, &transparent_prefixes)?;
125	
126	    if rewritten == cmd {
127	        return None;
128	    }
129	
130	    Some(rewritten)
131	}
132	
133	fn handle_vscode(cmd: &str) -> Result<()> {
134	    let verdict = permissions::check_command(cmd);
135	    if verdict == PermissionVerdict::Deny {
136	        audit_log("deny", cmd, "");
137	        return Ok(());
138	    }
139	
140	    let rewritten = match get_rewritten(cmd) {
141	        Some(r) => r,
142	        None => return Ok(()),
143	    };
144	
145	    // Allow (explicit rule matched): auto-allow the rewritten command.
146	    // Ask/Default (no allow rule matched): rewrite but let the host tool prompt.
147	    let decision = match verdict {
148	        PermissionVerdict::Allow => "allow",
149	        _ => "ask",
150	    };
151	
152	    audit_log("rewrite", cmd, &rewritten);
153	
154	    let output = json!({
155	        "hookSpecificOutput": {
156	            "hookEventName": PRE_TOOL_USE_KEY,
157	            "permissionDecision": decision,
158	            "permissionDecisionReason": "RTK auto-rewrite",
159	            "updatedInput": { "command": rewritten }
160	        }
161	    });
162	    let _ = writeln!(io::stdout(), "{output}");
163	    Ok(())
164	}
165	
166	fn handle_copilot_cli(cmd: &str, args: &Value) -> Result<()> {
167	    if let Some(response) = copilot_cli_response(cmd, args) {
168	        let _ = writeln!(io::stdout(), "{response}");
169	    }
170	    Ok(())
171	}
172	
173	fn copilot_cli_response(cmd: &str, args: &Value) -> Option<Value> {
174	    copilot_cli_response_for_verdict(cmd, args, permissions::check_command(cmd))
175	}
176	
177	fn copilot_cli_response_for_verdict(
178	    cmd: &str,
179	    args: &Value,
180	    verdict: PermissionVerdict,
181	) -> Option<Value> {
182	    if verdict == PermissionVerdict::Deny {
183	        audit_log("deny", cmd, "");
184	        return None;
185	    }
186	    let rewritten = get_rewritten(cmd)?;
187	    audit_log("rewrite", cmd, &rewritten);
188	
189	    let mut modified = args.clone();
190	    if let Some(obj) = modified.as_object_mut() {
191	        obj.insert("command".into(), Value::String(rewritten));
192	    }
193	
194	    // Copilot CLI v1.0.54 only applies `modifiedArgs` when permissionDecision is
195	    // either "allow" or absent. Omitting permissionDecision lets Copilot's normal
196	    // permission flow run on the rewritten command — `rtk *` is not on its
197	    // auto-allow list, so the user sees a prompt for the rewritten command.
198	    let mut response = json!({
199	        "permissionDecisionReason": "RTK auto-rewrite",
200	        "modifiedArgs": modified,
201	    });
202	    if verdict == PermissionVerdict::Allow {
203	        response["permissionDecision"] = json!("allow");
204	    }
205	    Some(response)
206	}
