208	// ── Gemini hook ───────────────────────────────────────────────
209	
210	/// Run the Gemini CLI BeforeTool hook.
211	pub fn run_gemini() -> Result<()> {
212	    let input = read_stdin_limited()?;
213	
214	    let json: Value = serde_json::from_str(&input).context("Failed to parse hook input as JSON")?;
215	
216	    let tool_name = json.get("tool_name").and_then(|v| v.as_str()).unwrap_or("");
217	
218	    if tool_name != "run_shell_command" {
219	        print_allow();
220	        return Ok(());
221	    }
222	
223	    let cmd = json
224	        .pointer("/tool_input/command")
225	        .and_then(|v| v.as_str())
226	        .unwrap_or("");
227	
228	    if cmd.is_empty() {
229	        print_allow();
230	        return Ok(());
231	    }
232	
233	    // Check deny rules — Gemini CLI only supports allow/deny (no ask mode).
234	    if permissions::check_command(cmd) == PermissionVerdict::Deny {
235	        let _ = writeln!(
236	            io::stdout(),
237	            r#"{{"decision":"deny","reason":"Blocked by RTK permission rule"}}"#
238	        );
239	        return Ok(());
240	    }
241	
242	    let (excluded, transparent_prefixes) = crate::core::config::Config::load()
243	        .map(|c| (c.hooks.exclude_commands, c.hooks.transparent_prefixes))
244	        .unwrap_or_default();
245	
246	    match rewrite_command(cmd, &excluded, &transparent_prefixes) {
247	        Some(ref rewritten) => {
248	            audit_log("rewrite", cmd, rewritten);
249	            print_rewrite(rewritten);
250	        }
251	        None => print_allow(),
252	    }
253	
254	    Ok(())
255	}
256	
257	fn print_allow() {
258	    let _ = writeln!(io::stdout(), r#"{{"decision":"allow"}}"#);
259	}
260	
261	fn print_rewrite(cmd: &str) {
262	    let output = serde_json::json!({
263	        "decision": "allow",
264	        "hookSpecificOutput": {
265	            "tool_input": {
266	                "command": cmd
267	            }
268	        }
269	    });
270	    let _ = writeln!(io::stdout(), "{}", output);
271	}
