274	
275	/// Best-effort audit log when RTK_HOOK_AUDIT=1.
276	fn audit_log(action: &str, original: &str, rewritten: &str) {
277	    if std::env::var("RTK_HOOK_AUDIT").as_deref() != Ok("1") {
278	        return;
279	    }
280	    let _ = audit_log_inner(action, original, rewritten);
281	}
282	
283	/// Escape newlines to prevent log-line injection in the pipe-delimited audit log.
284	fn sanitize_log_field(s: &str) -> String {
285	    s.replace('\\', "\\\\")
286	        .replace('|', "\\|")
287	        .replace('\n', "\\n")
288	        .replace('\r', "\\r")
289	}
290	
291	fn audit_log_inner(action: &str, original: &str, rewritten: &str) -> Option<()> {
292	    let home = dirs::home_dir()?;
293	    let dir = home.join(".local").join("share").join("rtk");
294	    std::fs::create_dir_all(&dir).ok()?;
295	    let path = dir.join("hook-audit.log");
296	    let mut file = std::fs::OpenOptions::new()
297	        .create(true)
298	        .append(true)
299	        .open(path)
300	        .ok()?;
301	    let ts = chrono::Local::now().format("%Y-%m-%dT%H:%M:%S");
302	    writeln!(
303	        file,
304	        "{} | {} | {} | {}",
305	        ts,
306	        action,
307	        sanitize_log_field(original),
308	        sanitize_log_field(rewritten)
309	    )
310	    .ok()
311	}
