313	// ── Claude Code native hook ────────────────────────────────────
314	
315	enum PayloadAction {
316	    Rewrite {
317	        cmd: String,
318	        rewritten: String,
319	        output: Value,
320	    },
321	    Skip {
322	        reason: &'static str,
323	        cmd: String,
324	    },
325	    Ignore,
326	}
327	
328	fn process_claude_payload(v: &Value) -> PayloadAction {
329	    let cmd = match v
330	        .pointer("/tool_input/command")
331	        .and_then(|c| c.as_str())
332	        .filter(|c| !c.is_empty())
333	    {
334	        Some(c) => c,
335	        None => return PayloadAction::Ignore,
336	    };
337	
338	    let verdict = permissions::check_command(cmd);
339	    if verdict == PermissionVerdict::Deny {
340	        return PayloadAction::Skip {
341	            reason: "skip:deny_rule",
342	            cmd: cmd.to_string(),
343	        };
344	    }
345	
346	    let rewritten = match get_rewritten(cmd) {
347	        Some(r) => r,
348	        None => {
349	            return PayloadAction::Skip {
350	                reason: "skip:no_match",
351	                cmd: cmd.to_string(),
352	            }
353	        }
354	    };
355	
356	    let updated_input = {
357	        let mut ti = v.get("tool_input").cloned().unwrap_or_else(|| json!({}));
358	        if let Some(obj) = ti.as_object_mut() {
359	            obj.insert("command".into(), Value::String(rewritten.clone()));
360	        }
361	        ti
362	    };
363	
364	    let mut hook_output = json!({
365	        "hookEventName": PRE_TOOL_USE_KEY,
366	        "permissionDecisionReason": "RTK auto-rewrite",
367	        "updatedInput": updated_input
368	    });
369	
370	    if verdict == PermissionVerdict::Allow {
371	        hook_output
372	            .as_object_mut()
373	            .unwrap()
374	            .insert("permissionDecision".into(), json!("allow"));
375	    }
376	
377	    PayloadAction::Rewrite {
378	        cmd: cmd.to_string(),
379	        rewritten,
380	        output: json!({ "hookSpecificOutput": hook_output }),
381	    }
382	}
383	
384	// ── Budget check (PreToolUse) ──────────────────────────────────────────────
385	
386	/// Fail-open budget check. Returns true if the tool call should be BLOCKED.
387	///
388	/// Skipped entirely when RTK_BUDGET=0. On any internal error the function
389	/// logs a warning to stderr and returns false (allow), per fail-open policy.
390	fn check_budget_best_effort() -> bool {
391	    if std::env::var("RTK_BUDGET").as_deref() == Ok("0") {
392	        return false;
393	    }
394	    match check_budget() {
395	        Ok(blocked) => blocked,
396	        Err(e) => {
397	            let _ = writeln!(io::stderr(), "[rtk budget] warning: {e}");
398	            false // fail-open
399	        }
400	    }
401	}
402	
403	fn check_budget() -> anyhow::Result<bool> {
404	    let store = CostStore::new()?;
405	    let config = PolicyConfig::load();
406	    let engine = PolicyEngine::new(config);
407	
408	    let dev_id = std::env::var("USER")
409	        .or_else(|_| std::env::var("USERNAME"))
410	        .unwrap_or_else(|_| "unknown".to_string());
411	
412	    let project = std::env::current_dir()
413	        .ok()
414	        .and_then(|p| p.file_name().map(|n| n.to_string_lossy().into_owned()))
415	        .unwrap_or_else(|| "unknown".to_string());
416	
417	    match engine.evaluate(&store, &dev_id, &project) {
418	        Verdict::Block(msg) => {
419	            let _ = writeln!(
420	                io::stderr(),
421	                "[rtk budget] BLOCKED: {} — set RTK_BUDGET=0 to disable checks",
422	                msg
423	            );
424	            Ok(true)
425	        }
426	        Verdict::Warn(msg) => {
427	            let _ = writeln!(io::stderr(), "[rtk budget] WARNING: {}", msg);
428	            Ok(false)
429	        }
430	        Verdict::Allow => Ok(false),
431	    }
432	}
