434	/// Run the Claude Code PreToolUse hook natively.
435	pub fn run_claude() -> Result<()> {
436	    let input = read_stdin_limited()?;
437	
438	    let input = input.trim();
439	    if input.is_empty() {
440	        return Ok(());
441	    }
442	
443	    let v: Value = match serde_json::from_str(input) {
444	        Ok(v) => v,
445	        Err(e) => {
446	            let _ = writeln!(io::stderr(), "[rtk hook] Failed to parse JSON input: {e}");
447	            return Ok(());
448	        }
449	    };
450	
451	    let session_id = v
452	        .get("session_id")
453	        .and_then(|s| s.as_str())
454	        .unwrap_or("unknown")
455	        .to_string();
456	
457	    // Budget check runs first — a Block verdict returns early before any rewrite.
458	    if check_budget_best_effort() {
459	        return Ok(());
460	    }
461	
462	    capture_provenance_best_effort(&session_id);
463	    capture_pr_metadata_best_effort(&session_id);
464	
465	    match process_claude_payload(&v) {
466	        PayloadAction::Rewrite {
467	            cmd,
468	            rewritten,
469	            output,
470	        } => {
471	            audit_log("rewrite", &cmd, &rewritten);
472	            let _ = writeln!(io::stdout(), "{output}");
473	        }
474	        PayloadAction::Skip { reason, cmd } => {
475	            audit_log(reason, &cmd, "");
476	        }
477	        PayloadAction::Ignore => {}
478	    }
479	
480	    Ok(())
481	}
