492	// ── Cursor native hook ─────────────────────────────────────────
493	
494	/// Cursor on Windows ships hook payloads with one or more leading
495	/// UTF-8 BOMs (`EF BB BF`, sometimes doubled), which serde_json
496	/// refuses to parse. Strip them defensively so the rewrite path keeps
497	/// working instead of silently returning `{}`.
498	fn strip_leading_bom(input: &str) -> &str {
499	    let mut s = input;
500	    while let Some(rest) = s.strip_prefix('\u{feff}') {
501	        s = rest;
502	    }
503	    s
504	}
