506	/// Run the Cursor Agent hook natively.
507	pub fn run_cursor() -> Result<()> {
508	    let input = read_stdin_limited()?;
509	
510	    let input = strip_leading_bom(&input).trim();
511	    if input.is_empty() {
512	        let _ = writeln!(io::stdout(), "{{}}");
513	        return Ok(());
514	    }
515	
516	    let v: Value = match serde_json::from_str(input) {
517	        Ok(v) => v,
518	        Err(_) => {
519	            let _ = writeln!(io::stdout(), "{{}}");
520	            return Ok(());
521	        }
522	    };
523	
524	    let cmd = match v
525	        .pointer("/tool_input/command")
526	        .and_then(|c| c.as_str())
527	        .filter(|c| !c.is_empty())
528	    {
529	        Some(c) => c.to_string(),
530	        None => {
531	            let _ = writeln!(io::stdout(), "{{}}");
532	            return Ok(());
533	        }
534	    };
535	
536	    let verdict = permissions::check_command(&cmd);
537	    if verdict == PermissionVerdict::Deny {
538	        audit_log("deny", &cmd, "");
539	        let _ = writeln!(io::stdout(), "{{}}");
540	        return Ok(());
541	    }
542	
543	    let rewritten = match get_rewritten(&cmd) {
544	        Some(r) => r,
545	        None => {
546	            let _ = writeln!(io::stdout(), "{{}}");
547	            return Ok(());
548	        }
549	    };
550	
551	    // Cursor preToolUse currently enforces allow/deny only and can ignore
552	    // updated_input when permission is "ask". Use "allow" for rewritten
553	    // commands unless the command is explicitly denied above.
554	    let decision = "allow";
555	
556	    audit_log("rewrite", &cmd, &rewritten);
557	
558	    // `continue: true` mirrors the shape of every other Cursor hook
559	    // (afterShellExecution, beforeSubmitPrompt, stop, ...). Cursor's
560	    // preToolUse panel renders the JSON it received; without this field
561	    // the panel collapses to `Output: {}` even though the rewrite ran,
562	    // which makes the hook look broken to users.
563	    let output = json!({
564	        "continue": true,
565	        "permission": decision,
566	        "updated_input": { "command": rewritten }
567	    });
568	    let _ = writeln!(io::stdout(), "{output}");
569	    Ok(())
570	}
