578	fn run_cursor_inner_with_rules(
579	    input: &str,
580	    deny_rules: &[String],
581	    ask_rules: &[String],
582	    allow_rules: &[String],
583	) -> String {
584	    let input = strip_leading_bom(input);
585	    let v: Value = match serde_json::from_str(input) {
586	        Ok(v) => v,
587	        Err(_) => return "{}".to_string(),
588	    };
589	
590	    let cmd = match v
591	        .pointer("/tool_input/command")
592	        .and_then(|c| c.as_str())
593	        .filter(|c| !c.is_empty())
594	    {
595	        Some(c) => c.to_string(),
596	        None => return "{}".to_string(),
597	    };
598	
599	    let verdict = permissions::check_command_with_rules(&cmd, deny_rules, ask_rules, allow_rules);
600	    if verdict == PermissionVerdict::Deny {
601	        return "{}".to_string();
602	    }
603	
604	    match get_rewritten(&cmd) {
605	        Some(rewritten) => {
606	            let decision = "allow";
607	            let output = json!({
608	                "continue": true,
609	                "permission": decision,
610	                "updated_input": { "command": rewritten }
611	            });
612	            output.to_string()
613	        }
614	        None => "{}".to_string(),
615	    }
616	}
