618	// ── PR metadata capture ────────────────────────────────────────
619	//
620	// Detect the current PR/feature context from env vars or branch name (<1ms,
621	// no network calls) and write it to a per-session sidecar file. The cost
622	// attribution command reads these files to link sessions to PRs.
623	
624	fn capture_pr_metadata_best_effort(session_id: &str) {
625	    if std::env::var("RTK_PROVENANCE").as_deref() == Ok("0") {
626	        return;
627	    }
628	    if let Err(e) = capture_pr_metadata(session_id) {
629	        let _ = writeln!(io::stderr(), "[rtk pr-meta] {e}");
630	    }
631	}
632	
633	fn capture_pr_metadata(session_id: &str) -> anyhow::Result<()> {
634	    let pr_ref = pr_linker::detect_pr_ref();
635	    let feature_tag = pr_linker::detect_feature_tag();
636	
637	    // Nothing to record if both are absent
638	    if pr_ref.is_none() && feature_tag.is_none() {
639	        return Ok(());
640	    }
641	
642	    let data_dir = dirs::data_local_dir()
643	        .unwrap_or_else(|| std::path::PathBuf::from("."))
644	        .join(crate::core::constants::RTK_DATA_DIR)
645	        .join("session-meta");
646	
647	    std::fs::create_dir_all(&data_dir)?;
648	
649	    let meta_path = data_dir.join(format!("{}.json", session_id));
650	
651	    // Skip write if file already exists (first hook call wins; branch won't change
652	    // mid-session and re-writing on every tool call wastes I/O).
653	    if meta_path.exists() {
654	        return Ok(());
655	    }
656	
657	    let meta = serde_json::json!({
658	        "session_id": session_id,
659	        "pr_ref": pr_ref,
660	        "feature_tag": feature_tag,
661	        "captured_at": chrono::Utc::now().to_rfc3339(),
662	    });
663	
664	    std::fs::write(&meta_path, serde_json::to_string(&meta)?)?;
665	    Ok(())
666	}
