668	// ── Provenance capture (diff-on-next-PreToolUse) ───────────────
669	//
670	// Each PreToolUse invocation is a separate OS process. We diff the
671	// working tree against the last snapshot stored in SQLite to detect
672	// what the PREVIOUS tool call changed.
673	
674	fn capture_provenance_best_effort(session_id: &str) {
675	    if std::env::var("RTK_PROVENANCE").as_deref() == Ok("0") {
676	        return;
677	    }
678	    if let Err(e) = capture_provenance(session_id) {
679	        let _ = writeln!(io::stderr(), "[rtk provenance] {e}");
680	    }
681	}
682	
683	fn capture_provenance(session_id: &str) -> Result<()> {
684	    let store = ProvenanceStore::new()?;
685	    let cwd = std::env::current_dir()?;
686	
687	    let tracked_files = collect_tracked_files(&cwd)?;
688	
689	    let mut new_provenance = Vec::new();
690	    for file_path in &tracked_files {
691	        let mtime = file_path
692	            .metadata()
693	            .and_then(|m| m.modified())
694	            .ok();
695	        if let Some(mt) = mtime {
696	            let age = mt.elapsed().unwrap_or_default();
697	            if age.as_secs() > 30 {
698	                continue;
699	            }
700	        }
701	
702	        let rel = file_path
703	            .strip_prefix(&cwd)
704	            .unwrap_or(file_path)
705	            .to_string_lossy()
706	            .replace('\\', "/");
707	
708	        let current_hash = match content_hash::hash_file(file_path) {
709	            Ok(h) => h,
710	            Err(_) => continue,
711	        };
712	
713	        let prev_hash = store.get_snapshot(&rel)?;
714	        if prev_hash.as_deref() == Some(&current_hash) {
715	            continue;
716	        }
717	
718	        if prev_hash.is_some() {
719	            let content = std::fs::read(file_path).unwrap_or_default();
720	            let line_count = content.iter().filter(|&&b| b == b'\n').count() as u32;
721	            let record = provenance::create_signed_record(
722	                &rel,
723	                &content,
724	                1,
725	                line_count.max(1),
726	                session_id,
727	            )?;
728	            new_provenance.push(record);
729	        }
730	
731	        store.save_snapshot(&rel, &current_hash)?;
732	    }
733	
734	    for record in &new_provenance {
735	        store.record_provenance(record)?;
736	    }
737	
738	    Ok(())
739	}
740	
741	fn collect_tracked_files(cwd: &std::path::Path) -> Result<Vec<std::path::PathBuf>> {
742	    let output = std::process::Command::new("git")
743	        .args(["ls-files", "--cached", "--others", "--exclude-standard", "-z"])
744	        .current_dir(cwd)
745	        .output();
746	
747	    let output = match output {
748	        Ok(o) if o.status.success() => o,
749	        _ => return Ok(Vec::new()),
750	    };
751	
752	    let files: Vec<std::path::PathBuf> = output
753	        .stdout
754	        .split(|&b| b == 0)
755	        .filter(|s| !s.is_empty())
756	        .filter_map(|s| std::str::from_utf8(s).ok())
757	        .filter(|s| {
758	            let ext = std::path::Path::new(s)
759	                .extension()
760	                .and_then(|e| e.to_str())
761	                .unwrap_or("");
762	            matches!(
763	                ext,
764	                "rs" | "ts" | "tsx" | "js" | "jsx" | "py" | "go" | "java"
765	                    | "kt" | "swift" | "cs" | "rb" | "sh" | "sql" | "toml"
766	                    | "yaml" | "yml" | "json" | "md"
767	            )
768	        })
769	        .map(|s| cwd.join(s))
770	        .collect();
771	
772	    Ok(files)
773	}
