139	    /// Fetch all records for a given PR ref.
140	    pub fn query_by_pr(&self, pr_ref: &str) -> Result<Vec<CostRecord>> {
141	        let mut stmt = self.conn.prepare(
142	            "SELECT id, session_id, model_id, input_tokens, output_tokens,
143	                    cache_read_tokens, cache_write_tokens, cost_usd,
144	                    pr_ref, feature_tag, project_path, developer_id, timestamp
145	             FROM cost_records WHERE pr_ref = ?1 ORDER BY timestamp ASC",
146	        )?;
147	        collect_records(&mut stmt, params![pr_ref])
148	    }
