150	    /// Fetch all records for a given developer.
151	    pub fn query_by_dev(&self, developer_id: &str) -> Result<Vec<CostRecord>> {
152	        let mut stmt = self.conn.prepare(
153	            "SELECT id, session_id, model_id, input_tokens, output_tokens,
154	                    cache_read_tokens, cache_write_tokens, cost_usd,
155	                    pr_ref, feature_tag, project_path, developer_id, timestamp
156	             FROM cost_records WHERE developer_id = ?1 ORDER BY timestamp ASC",
157	        )?;
158	        collect_records(&mut stmt, params![developer_id])
