161	    /// Fetch all records for a given model.
162	    pub fn query_by_model(&self, model_id: &str) -> Result<Vec<CostRecord>> {
163	        let mut stmt = self.conn.prepare(
164	            "SELECT id, session_id, model_id, input_tokens, output_tokens,
165	                    cache_read_tokens, cache_write_tokens, cost_usd,
166	                    pr_ref, feature_tag, project_path, developer_id, timestamp
167	             FROM cost_records WHERE model_id LIKE ?1 ORDER BY timestamp ASC",
168	        )?;
169	        // Use LIKE prefix so "claude-opus-4%" matches versioned IDs too
170	        let pattern = format!("{}%", model_id);
171	        collect_records(&mut stmt, params![pattern])
