178	                    cache_read_tokens, cache_write_tokens, cost_usd,
179	                    pr_ref, feature_tag, project_path, developer_id, timestamp
180	             FROM cost_records WHERE timestamp LIKE ?1 ORDER BY timestamp ASC",
181	        )?;
182	        let pattern = format!("{}%", date);
183	        collect_records(&mut stmt, params![pattern])
