186	    /// Sum total cost across all records (optionally filtered by project path).
187	    pub fn total_cost(&self, project_path: Option<&str>) -> Result<f64> {
188	        let total: f64 = if let Some(path) = project_path {
189	            self.conn.query_row(
190	                "SELECT COALESCE(SUM(cost_usd), 0.0) FROM cost_records WHERE project_path = ?1",
191	                params![path],
192	                |row| row.get(0),
193	            )?
194	        } else {
195	            self.conn.query_row(
196	                "SELECT COALESCE(SUM(cost_usd), 0.0) FROM cost_records",
197	                [],
198	                |row| row.get(0),
199	            )?
200	        };
201	        Ok(total)
202	    }
