292	fn map_record(row: &rusqlite::Row<'_>) -> rusqlite::Result<CostRecord> {
293	    Ok(CostRecord {
294	        id: Some(row.get(0)?),
295	        session_id: row.get(1)?,
296	        model_id: row.get(2)?,
297	        input_tokens: row.get::<_, i64>(3)?.max(0) as u64,
298	        output_tokens: row.get::<_, i64>(4)?.max(0) as u64,
299	        cache_read_tokens: row.get::<_, i64>(5)?.max(0) as u64,
300	        cache_write_tokens: row.get::<_, i64>(6)?.max(0) as u64,
301	        cost_usd: row.get(7)?,
302	        pr_ref: row.get(8)?,
303	        feature_tag: row.get(9)?,
304	        project_path: row.get(10)?,
305	        developer_id: row.get(11)?,
306	        timestamp: row.get(12)?,
307	    })
308	}
309	
310	fn collect_records(
311	    stmt: &mut rusqlite::Statement<'_>,
312	    params: impl rusqlite::Params,
313	) -> Result<Vec<CostRecord>> {
314	    let rows = stmt
315	        .query_map(params, map_record)?
316	        .collect::<std::result::Result<Vec<_>, _>>()?;
317	    Ok(rows)
318	}
319	
320	fn collect_summaries(stmt: &mut rusqlite::Statement<'_>) -> Result<Vec<CostSummary>> {
321	    let rows = stmt
322	        .query_map([], |row| {
323	            Ok(CostSummary {
324	                key: row.get(0)?,
325	                total_cost_usd: row.get(1)?,
326	                record_count: row.get::<_, i64>(2)? as u64,
327	                input_tokens: row.get::<_, i64>(3)? as u64,
328	                output_tokens: row.get::<_, i64>(4)? as u64,
329	            })
330	        })?
331	        .collect::<std::result::Result<Vec<_>, _>>()?;
332	    Ok(rows)
333	}
