337	fn get_db_path() -> Result<PathBuf> {
338	    if let Ok(custom) = std::env::var("RTK_COST_DB") {
339	        return Ok(PathBuf::from(custom));
340	    }
341	    let data_dir = dirs::data_local_dir().unwrap_or_else(|| PathBuf::from("."));
342	    Ok(data_dir.join(RTK_DATA_DIR).join(COST_DB))
343	}
